/**
 * Section schema, page blueprints and treatment field schema.
 *
 * This file is the single source of truth for:
 *  - the "Page sections" meta box (backend editing),
 *  - the Elementor widgets generated by includes/elementor.php,
 *  - sanitisation of stored data,
 *  - the demo importer (which seeds pages from the same defaults).
 *
 * A section field key is also the argument key accepted by the matching
 * theme renderer (wla_render_*_section), so no mapping layer is required.
 *
 * @package WeightLossAffordable_Core
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Repeater field helper.
 *
 * @param string $key    Field key.
 * @param string $label  Human label.
 * @param array  $fields Sub-fields keyed by key => [label, type, default].
 * @param array  $extra  Extra args (default rows).
 * @return array
 */
function wla_schema_repeater( $key, $label, $fields, $extra = array() ) {
	return array_merge(
		array(
			'key'    => $key,
			'label'  => $label,
			'type'   => 'repeater',
			'fields' => $fields,
			'default' => array(),
			'help'   => '',
		),
		$extra
	);
}

