/**
 * Section types in display order.
 *
 * @return array
 */
function wla_section_types() {
	return array_keys( wla_section_schema() );
}

/**
 * Defaults for one section type, derived from the schema.
 *
 * @param string $type Section type.
 * @return array
 */
function wla_section_defaults( $type ) {
	$schema = wla_section_schema();
	if ( ! isset( $schema[ $type ] ) ) {
		return array();
	}
	$defaults = array();
	foreach ( $schema[ $type ]['fields'] as $field ) {
		$defaults[ $field['key'] ] = isset( $field['default'] ) ? $field['default'] : '';
	}
	return $defaults;
}

/**
 * Validate/normalise stored section data against the schema.
 *
 * @param string $type   Section type.
 * @param array  $fields Raw field values.
 * @return array
 */
function wla_normalize_section( $type, $fields ) {
	$schema = wla_section_schema();
	if ( ! isset( $schema[ $type ] ) ) {
		return array();
	}
	$fields = is_array( $fields ) ? $fields : array();
	$out    = wla_section_defaults( $type );
	foreach ( $schema[ $type ]['fields'] as $field ) {
		$key = $field['key'];
		if ( 'repeater' === $field['type'] ) {
			$rows = isset( $fields[ $key ] ) && is_array( $fields[ $key ] ) ? $fields[ $key ] : array();
			if ( empty( $rows ) ) {
				$out[ $key ] = isset( $field['default'] ) ? $field['default'] : array();
				continue;
			}
			$clean = array();
			foreach ( $rows as $row ) {
				if ( ! is_array( $row ) ) {
					continue;
				}
				$item = array();
				$keep = false;
				foreach ( $field['fields'] as $sub_key => $sub ) {
					$value           = isset( $row[ $sub_key ] ) ? $row[ $sub_key ] : '';
					$value           = 'textarea' === $sub['type'] ? sanitize_textarea_field( $value ) : sanitize_text_field( $value );
					$item[ $sub_key ] = $value;
					if ( '' !== $value ) {
						$keep = true;
					}
				}
				if ( $keep ) {
					$clean[] = $item;
				}
			}
			$out[ $key ] = $clean;
			continue;
		}

		if ( ! isset( $fields[ $key ] ) ) {
			continue;
		}
		$value = $fields[ $key ];
		switch ( $field['type'] ) {
			case 'media':
				$out[ $key ] = is_numeric( $value ) ? absint( $value ) : sanitize_text_field( $value );
				break;
			case 'wysiwyg':
				$out[ $key ] = wp_kses_post( $value );
				break;
			case 'textarea':
				$out[ $key ] = sanitize_textarea_field( $value );
				break;
			case 'select':
				$options     = isset( $field['options'] ) ? array_keys( $field['options'] ) : array();
				$out[ $key ] = in_array( (string) $value, array_map( 'strval', $options ), true ) ? sanitize_text_field( $value ) : (string) $field['default'];
				break;
			default:
				// Link fields must not accept javascript:/data: schemes.
				if ( preg_match( '/(^|_)(url|link|href)$/', $key ) ) {
					$out[ $key ] = esc_url_raw( trim( (string) $value ) );
				} else {
					$out[ $key ] = sanitize_text_field( $value );
				}
		}
	}
	return $out;
}

/**
 * Convert a raw repeater value into the array shape expected by theme renderers.
 *
 * @param mixed  $rows  Repeater rows (associative).
 * @param string $shape 'pairs' (value,label style) or 'assoc'.
 * @param array  $keys  Ordered key list for 'pairs'.
 * @return array
 */
function wla_repeater_to_pairs( $rows, $keys ) {
	$out  = array();
	$rows = is_array( $rows ) ? $rows : array();
	foreach ( $rows as $row ) {
		if ( ! is_array( $row ) ) {
			continue;
		}
		$pair = array();
		foreach ( $keys as $key ) {
			$pair[] = isset( $row[ $key ] ) ? $row[ $key ] : '';
		}
		$out[] = $pair;
	}
	return $out;
}

/**
 * Turn a textarea of "one item per line" into an array.
 *
 * @param string $text Raw text.
 * @return array
 */
function wla_lines_to_array( $text ) {
	if ( is_array( $text ) ) {
		return array_values( array_filter( array_map( 'trim', $text ) ) );
	}
	$lines = preg_split( '/\r\n|\r|\n/', (string) $text );
	return array_values( array_filter( array_map( 'trim', (array) $lines ), 'strlen' ) );
}

/**
 * Turn "value|label" lines into an array of pairs.
 *
 * @param string $text Raw text.
 * @return array
 */
function wla_lines_to_pairs( $text ) {
	$out = array();
	foreach ( wla_lines_to_array( $text ) as $line ) {
		$parts = array_map( 'trim', explode( '|', $line, 2 ) );
		if ( count( $parts ) < 2 ) {
			$parts[] = $parts[0];
		}
		$out[] = array( sanitize_key( $parts[0] ), $parts[1] );
	}
	return $out;
}

